import json,urllib.request,base64,collections
pw=[l.split('=',1)[1].strip() for l in open('/home/judge/solution/deploy/compose/.env') if l.startswith('DITTO_PASSWORD=')][0]
H={'Authorization':'Basic '+base64.b64encode(f'ditto:{pw}'.encode()).decode()}
out=[];cur=None
while True:
    u='http://127.0.0.1:8080/api/2/search/things?namespaces=org.openegiz.zhezkazgan&option=size(200)'+(f',cursor({cur})' if cur else '')
    j=json.load(urllib.request.urlopen(urllib.request.Request(u,headers=H))); out+=j['items']; cur=j.get('cursor')
    if not cur: break
F=lambda t:{k:v['properties'].get('value') for k,v in t.get('features',{}).items()}
ch={t['thingId'].split(':')[1]:F(t) for t in out if t['thingId'].split(':')[1].startswith('k')}
print('verdicts',collections.Counter(v['verdict'] for v in ch.values()))
print('states',collections.Counter(v['state'] for v in ch.values()))
for k,v in sorted(ch.items()):
    if v['verdict']!='разрешено' or v['people']: print(k,v['verdict'],v['reason'],v['state'],v['crew'],v['equipment'],v['air'],v['air_required'],v['stage_progress'])
pil={t['thingId'].split(':')[1]:F(t) for t in out if t['thingId'].split(':')[1].startswith('c')}
print('pillars',collections.Counter(v['status'] for v in pil.values()), 'minSF',min((v['sf'],k) for k,v in pil.items()))
for t in out:
    n=t['thingId'].split(':')[1]
    if n.startswith(('pdm','sbu','rs-','hoist','crusher','crew')): print(n,F(t))
EOF
python3 /tmp/all.py | cut -c1-400

